Gọi bằng Postman thì chạy, trên trình duyệt báo lỗi CORS. Giải thích trình duyệt đã làm gì và server cần trả về những header nào.

answer_key.reference_solution:
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const IDEMPOTENT = ['GET', 'HEAD', 'PUT', 'DELETE'];

async function fetchWithRetry(url, options = {}, { retries = 3, baseDelay = 300 } = {}) {
  const canRetry = IDEMPOTENT.includes((options.method || 'GET').toUpperCase());
  for (let attempt = 0; ; attempt++) {
    let res;
    try {
      res = await fetch(url, options);
    } catch (err) {
      if (!canRetry || attempt >= retries || err.name === 'AbortError') throw err;
      await sleep(baseDelay * 2 ** attempt);
      continue;
    }
    const retryable = res.status === 429 || res.status >= 500;
    if (!retryable || !canRetry || attempt >= retries) return res;
    const after = Number(res.headers.get('Retry-After'));
    await sleep(res.status === 429 && after > 0 ? after * 1000 : baseDelay * 2 ** attempt);
  }
}

describe('formatPrice', () => {
  test('định dạng hàng triệu', () => {
    expect(formatPrice(1500000)).toBe('1.500.000 ₫');
  });
  test('số 0', () => {
